const input = $input.first()?.json || {};
return [{
  json: {
    company_name: input.company_name || "Apex Global Logistics",
    website: input.website || "https://apex-global-logistics-example.com",
    industry: input.industry || "Logistics & Freight",
    headcount: parseInt(input.headcount || 180, 10),
    country: input.country || "United States",
    decision_maker_name: input.decision_maker_name || "Marcus Vance",
    decision_maker_title: input.decision_maker_title || "Chief Financial Officer",
    decision_maker_email: input.decision_maker_email || "marcus.v@apexlogistics-demo.com",
    verified_unfilled_job_req_days: input.verified_unfilled_job_req_days !== undefined ? input.verified_unfilled_job_req_days : 45,
    c_suite_hired_last_90_days: input.c_suite_hired_last_90_days !== undefined ? input.c_suite_hired_last_90_days : true,
    dm_verified_email: true,
    dm_linkedin_active: true,
    observed_signals: input.observed_signals || "Active job requisition for Power BI Analyst open for 45 days; 3 new regional hubs opened."
  }
}];

const account = $input.first().json;

const priorityVerticals = [
  'logistics', 'freight', 'supply chain', 'distribution', 'manufacturing',
  'saas', 'software', 'fintech', 'legal', 'wealth management', 'healthcare tech'
];
const tier1Countries = ['united states', 'usa', 'us', 'united kingdom', 'uk', 'uae', 'united arab emirates'];
const tier2Countries = ['canada', 'australia', 'netherlands', 'switzerland', 'germany'];

let breakdown = {
  vertical_fit: 0,
  company_scale: 0,
  demonstrated_problem: 0,
  buying_signals: 0,
  decision_maker: 0,
  geographic_fit: 0
};

// 1. Vertical Fit
const ind = (account.industry || '').toLowerCase();
if (priorityVerticals.some(v => ind.includes(v))) {
  breakdown.vertical_fit = 20;
} else {
  breakdown.vertical_fit = 10;
}

// 2. Company Scale
const hc = account.headcount || 0;
if (hc >= 50 && hc <= 500) {
  breakdown.company_scale = 20;
} else if ((hc >= 25 && hc < 50) || (hc > 500 && hc <= 1000)) {
  breakdown.company_scale = 14;
} else {
  breakdown.company_scale = 8;
}

// 3. Demonstrated Business Problem
if (account.verified_unfilled_job_req_days >= 35) {
  breakdown.demonstrated_problem = 20;
} else {
  breakdown.demonstrated_problem = 12;
}

// 4. Buying Signals
if (account.c_suite_hired_last_90_days) {
  breakdown.buying_signals = 20;
} else {
  breakdown.buying_signals = 10;
}

// 5. Decision Maker Accessibility
if (account.dm_verified_email && account.dm_linkedin_active) {
  breakdown.decision_maker = 10;
} else if (account.dm_verified_email) {
  breakdown.decision_maker = 6;
} else {
  breakdown.decision_maker = 2;
}

// 6. Geographic Fit
const country = (account.country || '').toLowerCase();
if (tier1Countries.some(c => country.includes(c))) {
  breakdown.geographic_fit = 10;
} else if (tier2Countries.some(c => country.includes(c))) {
  breakdown.geographic_fit = 6;
} else {
  breakdown.geographic_fit = 3;
}

const totalScore = Object.values(breakdown).reduce((a, b) => a + b, 0);
let tier = 'Tier C';
let recommendedService = 'Business Requirements Analysis';
let wedgeOffer = 'Operational Process Map';

if (totalScore >= 80) {
  tier = 'Tier A';
  recommendedService = 'Microsoft Power BI Modernization';
  wedgeOffer = '5-Day Executive KPI Sprint';
} else if (totalScore >= 60) {
  tier = 'Tier B';
  recommendedService = 'AI Agents & Workflow Automation';
  wedgeOffer = 'Workflow Bottleneck Audit';
}

return [{
  json: {
    ...account,
    qualification: {
      lead_score: totalScore,
      tier,
      recommended_service: recommendedService,
      wedge_offer: wedgeOffer,
      breakdown
    }
  }
}];

const lead = $input.first().json;

const firstName = (lead.decision_maker_name || '').split(' ')[0] || 'there';
const company = lead.company_name || 'your company';
const wedge = lead.qualification.wedge_offer;
const service = lead.qualification.recommended_service;

const email1 = {
  subject: `Question regarding ${company}'s reporting latency`,
  body: `Hi ${firstName},\n\nI noticed ${company} has been seeking a BI & Analytics specialist for over a month to support operational reporting.\n\nWhen freight networks scale across regional hubs, consolidating disparate dispatch and accounting metrics in Excel typically costs finance teams 12-15 hours each week.\n\nAt Zenthra Systems, we engineer automated ${service} architectures. We recently helped a multi-hub logistics firm eliminate 14 weekly hours of spreadsheet assembly using our ${wedge}.\n\nWould it make sense to review a 3-minute video teardown of how this dashboard connects directly to your dispatch ERP?\n\nBest regards,\nZenthra Systems Enterprise Sales\nhttps://zenthra-systems.example.com`
};

const email2 = {
  subject: `3 ideas for ${company}'s executive KPI visibility`,
  body: `Hi ${firstName},\n\nFollowing up on my previous note. Most CFOs we speak with in ${lead.industry} want live gross margin by route without waiting for month-end close.\n\nIf you're open to it, I can share a sample interactive Power BI dashboard framework designed specifically for logistics freight operations.\n\nAre you free for 10 minutes this Thursday afternoon?\n\nBest,\nZenthra Systems`
};

const linkedin = `Hi ${firstName}, saw your focus on operational scale at ${company}. We help logistics leaders eliminate manual reporting debt with custom Power BI & AI workflows. Would love to connect and share notes.`;

return [{
  json: {
    ...lead,
    outreach_package: {
      touch_1_email: email1,
      touch_2_email: email2,
      linkedin_message: linkedin
    }
  }
}];

const item = $input.first().json;
return [{
  json: {
    execution_id: `ZENTHRA-${Date.now()}`,
    timestamp: new Date().toISOString(),
    status: "AWAITING_SDR_APPROVAL",
    company: item.company_name,
    contact_name: item.decision_maker_name,
    contact_title: item.decision_maker_title,
    contact_email: item.decision_maker_email,
    lead_score: item.qualification.lead_score,
    lead_tier: item.qualification.tier,
    service_recommended: item.qualification.recommended_service,
    wedge_offer: item.qualification.wedge_offer,
    score_breakdown: item.qualification.breakdown,
    outreach_email_1_subject: item.outreach_package.touch_1_email.subject,
    outreach_email_1_body: item.outreach_package.touch_1_email.body,
    outreach_linkedin: item.outreach_package.linkedin_message
  }
}];
